 interface Job{void run()throws Exception;}interface Result{void show()throws Exception;}
 void ui(Result action){Long owner=taskOwner.get();runOnUiThread(()->{if(!isFinishing()&&!isDestroyed()&&(owner==null||NavPolicy.owns(owner,epoch)))try{action.show();}catch(Exception e){message("无法显示数据，请刷新重试。");}});}
 void task(String text,Job action){task(text,action,true);}
 // Write lane: one change at a time, shown in the top progress bar. Read-only refreshes use load() instead.
 void task(String text,Job action,boolean lockData){if(busy){toast("上一项操作还在进行，请稍候。");return;}busy=true;long ticket=epoch;status.setText(text);status.setVisibility(View.VISIBLE);progress.setVisibility(View.VISIBLE);worker.execute(()->{taskOwner.set(ticket);try{if(lockData)synchronized(manager){action.run();}else action.run();}catch(Exception e){String msg=e instanceof Api.Error||e instanceof java.io.IOException?Book.safeMessage(e):"操作未完成，请检查设置并刷新核对。修改请求不会自动重发。";ui(()->message(msg));}finally{taskOwner.remove();runOnUiThread(()->{if(!isDestroyed()){busy=false;status.setVisibility(View.GONE);progress.setVisibility(View.INVISIBLE);}});}});}
 // Read lane: parallel, never blocks buttons; the same key is merged while in flight. Callbacks run on the UI thread.
 final Refresher refresher=new Refresher();final Map<String,List<Runnable>> waiting=new HashMap<>();final Map<String,String> loadErrors=new HashMap<>();
 final android.os.Handler later=new android.os.Handler(android.os.Looper.getMainLooper());final Map<String,Runnable> pendingRenders=new HashMap<>();final Map<String,String> fingerprints=new HashMap<>();android.animation.ObjectAnimator spinner;
 boolean loading(String key){return refresher.running(key);}
 void load(String key,Job fetch,Runnable done){if(!refresher.start(key)){if(done!=null)waiting.get(key).add(done);return;}List<Runnable> callbacks=new ArrayList<>();if(done!=null)callbacks.add(done);waiting.put(key,callbacks);spin();
  Manager.NET.execute(()->{String failure=null;try{fetch.run();}catch(Exception e){failure=e instanceof Api.Error||e instanceof java.io.IOException?Book.safeMessage(e):"读取失败";}final String error=failure;runOnUiThread(()->{refresher.finish(key,System.currentTimeMillis());List<Runnable> cbs=waiting.remove(key);if(error==null)loadErrors.remove(key);else loadErrors.put(key,error);spin();if(isFinishing()||isDestroyed()||cbs==null)return;for(Runnable r:cbs)try{r.run();}catch(Exception ignored){}});});}
 void loadIfDue(String key,long ttl,long checked,Job fetch,Runnable done){if(refresher.due(key,ttl,checked,System.currentTimeMillis()))load(key,fetch,done);}
 void spin(){if(refresh==null)return;boolean on=!refresher.idle();if(on&&spinner==null){spinner=android.animation.ObjectAnimator.ofFloat(refresh,"rotation",0f,360f);spinner.setDuration(900);spinner.setRepeatCount(android.animation.ValueAnimator.INFINITE);spinner.setInterpolator(new android.view.animation.LinearInterpolator());spinner.start();refresh.setContentDescription("正在更新");}else if(!on&&spinner!=null){spinner.cancel();spinner=null;refresh.setRotation(0f);refresh.setContentDescription("刷新当前页面");}}
 // Coalesce several results arriving together into one redraw; skip it when the page data did not change.
 void renderLater(String key,java.util.function.Supplier<String> fingerprint,Runnable render){Runnable old=pendingRenders.remove(key);if(old!=null)later.removeCallbacks(old);Runnable r=()->{pendingRenders.remove(key);String f=fingerprint.get();if(f!=null&&f.equals(fingerprints.get(key)))return;fingerprints.put(key,f);render.run();};pendingRenders.put(key,r);later.postDelayed(r,250);}
 void rendered(String key,String fingerprint){fingerprints.put(key,fingerprint);}
